<script setup>
import { router,useForm } from '@inertiajs/vue3';import{ref}from'vue';
defineProps({seasons:Array});const editing=ref(null);const form=useForm({name:'',start_date:'',end_date:'',is_active:true});const date=v=>new Date(`${String(v).slice(0,10)}T12:00:00`).toLocaleDateString('fr-CH');
function edit(s){editing.value=s;form.defaults({name:s.name,start_date:s.start_date,end_date:s.end_date,is_active:s.is_active});form.reset();form.clearErrors()}function cancel(){editing.value=null;form.defaults({name:'',start_date:'',end_date:'',is_active:true});form.reset()}function submit(){const o={preserveScroll:true,onSuccess:cancel};editing.value?form.put(`/admin/saisons/${editing.value.id}`,o):form.post('/admin/saisons',o)}function remove(s){confirm(`Supprimer « ${s.name} » ?`)&&router.delete(`/admin/saisons/${s.id}`,{preserveScroll:true})}
</script>
<template><section class="grid gap-6 lg:grid-cols-[.65fr_1.35fr]"><div class="rounded-3xl bg-white p-6"><p class="text-xs font-bold uppercase tracking-wider text-coral">{{editing?'Modification':'Nouvelle saison'}}</p><h2 class="mt-2 font-serif text-3xl">{{editing?'Modifier':'Créer une saison'}}</h2><form @submit.prevent="submit" class="mt-6 space-y-4"><input v-model="form.name" class="w-full rounded-xl border border-black/10 px-4 py-3" placeholder="Saison 2026–2027"/><div class="grid grid-cols-2 gap-3"><input v-model="form.start_date" type="date" class="rounded-xl border border-black/10 px-3 py-3"/><input v-model="form.end_date" type="date" class="rounded-xl border border-black/10 px-3 py-3"/></div><label class="flex gap-2 text-sm font-semibold"><input v-model="form.is_active" type="checkbox"/> Saison active</label><p v-if="Object.keys(form.errors).length" class="text-xs text-red-600">{{Object.values(form.errors)[0]}}</p><div class="flex gap-2"><button v-if="editing" type="button" @click="cancel" class="flex-1 rounded-full border py-3">Annuler</button><button class="flex-1 rounded-full bg-ink py-3 font-bold text-white">Enregistrer</button></div></form></div><div class="overflow-hidden rounded-3xl bg-white"><div class="border-b border-black/5 px-6 py-5"><h2 class="font-serif text-2xl">Saisons</h2><p class="mt-1 text-xs text-black/45">{{seasons.length}} saisons configurées</p></div><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-left"><thead class="bg-[#f7f5f0] text-[11px] font-bold uppercase tracking-wider text-black/45"><tr><th class="px-6 py-4">Saison</th><th class="px-5 py-4">Période</th><th class="px-5 py-4">Cours</th><th class="px-5 py-4">Statut</th><th class="px-6 py-4 text-right">Actions</th></tr></thead><tbody class="divide-y divide-black/5"><tr v-for="s in seasons" :key="s.id"><td class="px-6 py-5 font-bold">{{s.name}}</td><td class="px-5 py-5 text-sm">{{date(s.start_date)}} – {{date(s.end_date)}}</td><td class="px-5 py-5">{{s.courses_count}}</td><td class="px-5 py-5"><span class="rounded-full px-3 py-1 text-[10px] font-bold uppercase" :class="s.is_active?'bg-green-50 text-green-700':'bg-black/5 text-black/40'">{{s.is_active?'Active':'Archivée'}}</span></td><td class="px-6 py-5"><div class="flex justify-end gap-2"><button @click="edit(s)" class="grid h-9 w-9 place-items-center rounded-full bg-black/5">✎</button><button @click="remove(s)" :disabled="s.courses_count>0" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500 disabled:opacity-25">×</button></div></td></tr></tbody></table><p v-if="!seasons.length" class="p-16 text-center text-black/40">Aucune saison.</p></div></div></section></template>
